INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 2, 'theory', 'Quiz: branches, loops, and functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 0, 'What happens in a switch if you forget break in a case branch?', '["Execution \"falls through\" into the next branch", "The compiler refuses to build", "Only default runs", "The program ends with an error"]', 0, 'Fall-through is normal C behavior: after the branch body, control goes on until a break is met. Turn on -Wimplicit-fallthrough.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 1, 'How is the parameter int x passed to a function?', '["By reference: changes are visible to the caller", "Through a global variable", "By value: the function gets a copy", "Always through the stack, registers are not used"]', 2, 'In C all parameters are passed by value; to change someone else''s variable, you pass its address. The first arguments live in registers a0–a7.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 2, 'Why does the loop for (size_t i = n - 1; i >= 0; i--) never end?', '["size_t is signed", "Because n is small", "The compiler removes i--", "i >= 0 is always true for unsigned, and 0 - 1 gives the maximum"]', 3, 'An unsigned number is never less than zero; at i == 0 the decrement wraps around to SIZE_MAX. Write for (size_t i = n; i-- > 0; ) or use a signed type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 3, 'What is stored in register ra when a function is called with jal?', '["The function''s result", "The address of the instruction to return to after ret", "The stack pointer", "The first argument"]', 1, 'jal saves the address of the next instruction in ra; the called function puts it in its frame if needed, and ret jumps via ra.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 4, 'What is wrong with the expression int x = i++ + ++i;?', '["It is too long", "++i can''t be written on the right", "i changes twice between sequence points: undefined behavior", "The result is always 0"]', 2, 'The order of evaluating the operands of + is undefined, and changing one variable twice without a sequence point is UB. Change a variable at most once.');
